cd /app && cat > test/using.scratch5.test.ts <<'EOF'
import { describe, it } from 'vitest';
import { parseSource } from '../src/parser';
function show(l:string,f:()=>unknown){try{const a=f() as any;console.log('OK',l,a.body[0]?.type,a.body[0]?.left?.kind,a.body[0]?.await)}catch(e:any){console.log('ERR',l,e.message)}}
describe('scratch5',()=>{it('x',()=>{
show('for await (using of of [0,1,2]) module',()=>parseSource('for await (using of of [0,1,2]) {}',{next:true,sourceType:'module'}));
show('for await (await using of of [0,1,2]) module',()=>parseSource('for await (await using of of [0,1,2]) {}',{next:true,sourceType:'module'}));
show('for (using of of [0,1,2]) script',()=>parseSource('for (using of of [0,1,2]) {}',{next:true}));
});});
EOF
npx vitest run test/using.scratch5.test.ts > /tmp/using5.out 2>&1; cat /tmp/using5.out | sed -n '1,40p'

cd /app && cat > test/using.scratch23.test.ts <<'EOF'
import { describe, it } from 'vitest';
import { parseSource } from '../src/parser';
describe('x',()=>{it('x',()=>{try{const a=parseSource('for await (await using of of []) {}',{next:true,sourceType:'module'}) as any;console.log('OK',a.body[0].left.kind,a.body[0].left.declarations[0].id.name,a.body[0].await)}catch(e:any){console.log('ERR',e.message)}})});
EOF
npx vitest run test/using.scratch23.test.ts > /tmp/using23.out 2>&1; cat /tmp/using23.out | sed -n '1,10p'; rm -f test/using.scratch23.test.ts
